def name_operands(region,address,operation):
 if region=='Music' and address in FUNCTIONS:
  import re
  operation=re.sub(r'#([0-9A-F]{4})',lambda m:'@'+OPERANDS[int(m[1],16)] if int(m[1],16) in OPERANDS else m[0],operation)
  if address in SYNTH_STARTS:
   operation=operation.replace('BIT 5, D','BIT @MusicSampleConst.AccumShiftBit, D').replace('BIT 6, D','BIT @MusicSampleConst.AccumToneBit, D')
   operation=operation.replace('LD H, #DC','LD H, @MusicSampleConst.VolumePage').replace('LD H, #DD','LD H, @MusicSampleConst.PitchPage').replace('OR #F0','OR @MusicSampleConst.HighNibbleMask').replace('AND #1F','AND @MusicSampleConst.ShiftMask')
   operation=operation.replace('CP #1F','CP @MusicSampleConst.MaxAdjust').replace('CP #10','CP @MusicSampleConst.NibbleBoundary').replace('LD A, #0F','LD A, @MusicSampleConst.MaxLevel')
   channel=SYNTH_STARTS.index(address);operation=operation.replace('AND #'+('09','12','24')[channel],'AND @MusicSampleConst.MixerMask'+('A','B','C')[channel])
  if address==0xE1ED:operation=operation.replace('JR NZ, #E2CD','JR NZ, @Music.FinishChannelC.StoreSlideDelay').replace('JR #E2CD','JR @Music.FinishChannelC.StoreSlideDelay')
 return operation

